/* eslint-disable max-lines-per-function */

'use strict';

// MODULES //

var strokeCaps = require( '@stdlib/plot/vega/base/stroke-caps' );
var axisTickStyles = require( '@stdlib/plot/vega/axis/tick-styles' );


// MAIN //

/**
* Returns an editor configuration for title properties.
*
* @returns {Object} configuration
*
* @example
* var o = config();
* // returns {...}
*/
function config() {
	return {
		'domain': {
			'description': 'whether to include an axis baseline as part of an axis',
			'property': 'domain',
			'default': true,
			'type': 'boolean'
		},
		'domainCap': {
			'description': 'stroke cap for the axis domain line',
			'property': 'domainCap',
			'default': 'butt',
			'type': 'oneOf',
			'values': strokeCaps()
		},
		'domainColor': {
			'description': 'color of the axis domain line',
			'property': 'domainColor',
			'default': '#000',
			'type': 'color'
		},
		'domainDash': {
			'description': 'stroke dash of the axis domain line',
			'property': 'domainDash',
			'default': '',
			'type': 'string'
		},
		'domainDashOffset': {
			'description': 'pixel offset at which to start an axis domain line stroke dash',
			'property': 'domainDashOffset',
			'default': 0,
			'type': 'number',
			'units': 'px'
		},
		'domainOpacity': {
			'description': 'opacity of the axis domain line',
			'property': 'domainOpacity',
			'default': 1,
			'type': 'number',
			'min': 0,
			'max': 1
		},
		'domainWidth': {
			'description': 'stroke width of the axis domain line',
			'property': 'domainWidth',
			'default': 1,
			'type': 'number',
			'min': 0,
			'units': 'px'
		},
		'grid': {
			'description': 'whether to include grid lines as part of an axis',
			'property': 'grid',
			'default': false,
			'type': 'boolean'
		},
		'gridCap': {
			'description': 'stroke cap for axis grid lines',
			'property': 'gridCap',
			'default': 'butt',
			'type': 'oneOf',
			'values': strokeCaps()
		},
		'gridColor': {
			'description': 'color of axis grid lines',
			'property': 'gridColor',
			'default': '#000',
			'type': 'string'
		},
		'gridDash': {
			'description': 'stroke dash of axis grid lines',
			'property': 'gridDash',
			'default': '',
			'type': 'string'
		},
		'gridDashOffset': {
			'description': 'pixel offset at which to start an axis grid line stroke dash',
			'property': 'gridDashOffset',
			'default': 0,
			'type': 'number',
			'units': 'px'
		},
		'gridOpacity': {
			'description': 'opacity of axis grid lines',
			'property': 'gridOpacity',
			'default': 1,
			'type': 'number',
			'min': 0,
			'max': 1
		},
		'gridScale': {
			'description': 'name of the scale to use when rendering axis grid lines',
			'property': 'gridScale',
			'default': '',
			'type': 'string'
		},
		'gridWidth': {
			'description': 'stroke width of axis grid lines',
			'property': 'gridWidth',
			'default': 1,
			'type': 'number',
			'min': 0,
			'units': 'px'
		},
		'tickBand': {
			'description': 'axis tick style to use in conjunction with band scales',
			'property': 'tickBand',
			'default': '',
			'type': 'oneOf',
			'values': axisTickStyles()
		},
		'tickCap': {
			'description': 'stroke cap for axis tick marks',
			'property': 'tickCap',
			'default': 'butt',
			'type': 'oneOf',
			'values': strokeCaps()
		},
		'tickColor': {
			'description': 'color of axis tick marks',
			'property': 'tickColor',
			'default': '#000',
			'type': 'string'
		},
		'tickCount': {
			'description': 'number of axis tick marks for an axis visualizing a quantitative scale',
			'property': 'tickCount',
			'default': '',
			'type': 'string'
		},
		'tickDash': {
			'description': 'stroke dash of axis tick marks',
			'property': 'tickDash',
			'default': '',
			'type': 'string'
		},
		'tickDashOffset': {
			'description': 'pixel offset at which to start an axis tick mark stroke dash',
			'property': 'tickDashOffset',
			'default': 0,
			'type': 'number',
			'units': 'px'
		},
		'tickMinStep': {
			'description': 'minimum desired step between axis tick marks',
			'property': 'tickMinStep',
			'default': 0,
			'type': 'number',
			'min': 0
		},
		'tickOffset': {
			'description': 'position offset to apply to axis tick marks, labels, and gridlines',
			'property': 'tickOffset',
			'default': 0,
			'type': 'number',
			'units': 'px'
		},
		'tickOpacity': {
			'description': 'opacity of axis tick marks',
			'property': 'tickOpacity',
			'default': 1,
			'type': 'number',
			'min': 0,
			'max': 1
		},
		'ticks': {
			'description': 'whether to include axis tick marks as part of an axis',
			'property': 'ticks',
			'default': true,
			'type': 'boolean'
		},
		'tickSize': {
			'description': 'length of axis tick marks',
			'property': 'tickSize',
			'default': 1,
			'type': 'number',
			'min': 0,
			'units': 'px'
		},
		'tickWidth': {
			'description': 'width of axis tick marks',
			'property': 'tickWidth',
			'default': 1,
			'type': 'number',
			'min': 0,
			'units': 'px'
		},
		'title': {
			'description': 'title text',
			'property': 'title',
			'default': '',
			'type': 'string'
		},
		'titleColor': {
			'description': 'color of the title',
			'property': 'titleColor',
			'default': '#000',
			'type': 'color'
		},
		'titleFont': {
			'description': 'font of the title',
			'property': 'titleFont',
			'default': '',
			'type': 'string'
		},
		'titleOpacity': {
			'description': 'opacity of the title',
			'property': 'titleOpacity',
			'default': 0,
			'type': 'number',
			'min': 0,
			'max': 1
		}
	};
}


// EXPORTS //

module.exports = config;
